#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        
        int n;
        cin>>n;
        
        vector<int> a(3*n+1);
        
        for(int i=1;i<=3*n;i++) cin>>a[i];
        
        sort( a.begin()+1 , a.end());
        
        vector<long long> P(3*n +1,0);
        
        for(int i=1;i<= 3*n;i++){
            P[i] = P[i-1] +a[i];
        }
        
        auto get_V = [&](int c1, int c2) -> long long{
            return 6* P[3*n] - 2*P[3*n-c1] - P[3*n - c1- 2*c2] - 3* P[2*c1 + c2];
        };
        
        long long max_total_strength =0;
        
        for(int c1=0; c1<=n;c1++){
            long long max_for_c1 =0;
            
            auto check_c2 = [&] (int c2){
                if(c2 >=0 && c2<= n -c1){
                    max_for_c1=max(max_for_c1, get_V(c1,c2));
                }
            };
            
            check_c2(0);
            check_c2(n-c1);
            
            int low=0, high = n- c1-1;
            int opt_c2=0;
            
            while(low<=high){
                int mid = low+ (high-low)/2;
                
                long long delta = (a[ 3*n - c1- 2*mid]+ a[3*n- c1- 2*mid-1]) - 3* a[2*c1+mid +1];
                
                if(delta>=0){
                    opt_c2=mid+1;
                    low=mid+1;
                } else{
                    high=mid-1;
                }
            }
            
            for(int offset =-2;offset<= 2;++offset){
                check_c2(opt_c2 +offset);
            }
            
            max_total_strength= max(max_total_strength, max_for_c1);
            
        }
        
        cout<< max_total_strength<<"\n";
    }
}
